<script setup lang="ts">
import { computed, ref } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { api } from '@/api/client'
type Coach={id:number;name:string;email?:string};const coach=ref<number>();const day=ref(1);const starts=ref('09:00');const ends=ref('17:00');const msg=ref('');const err=ref('');const search=ref('');const coaches=useQuery({queryKey:['coaches'],queryFn:async()=>{const r=await api.get('/coaches');return r.data.data?.data??r.data.data??[]}});const list=computed<Coach[]>(()=>((coaches.data.value??[])as Coach[]).filter(item=>`${item.name} ${item.email??''}`.toLowerCase().includes(search.value.toLowerCase())))
async function save(){try{if(!coach.value)throw Error('Select a coach.');await api.put(`/coaches/${coach.value}/availability`,{availability:[{day_of_week:day.value,starts_at:starts.value,ends_at:ends.value}]});msg.value='Availability saved.'}catch(e:any){err.value=e.message==='Select a coach.'?e.message:e.response?.data?.message??'Could not save availability.'}}async function revenue(){try{if(!coach.value)throw Error('Select a coach.');const r=await api.get(`/coaches/${coach.value}/revenue`);msg.value=`Completed sessions: ${r.data.data.completed_sessions}; revenue: ₱${r.data.data.completed_revenue}`}catch(e:any){err.value=e.message==='Select a coach.'?e.message:e.response?.data?.message??'Could not load revenue.'}}</script>
<template><section class="panel membership-form payment-form"><h2>Coach operations</h2><form @submit.prevent="save"><label>Find coach<input v-model="search" placeholder="Name or email"/></label><label>Coach<select v-model.number="coach"><option :value="undefined">Select coach</option><option v-for="item in list" :key="item.id" :value="item.id">{{item.name}}{{item.email?` · ${item.email}`:''}}</option></select></label><label>Day<select v-model.number="day"><option v-for="(name,index) in ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']" :key="name" :value="index">{{name}}</option></select></label><label>Starts<input v-model="starts" type="time"/></label><label>Ends<input v-model="ends" type="time"/></label><button class="secondary-button">Save availability</button><button class="table-button" type="button" @click="revenue">View revenue</button></form><p class="muted">Saving replaces the coach's current weekly availability with this slot.</p><p v-if="msg" class="action-message success">{{msg}}</p><p v-if="err" class="action-message error">{{err}}</p></section></template>
